def refill(bucket, now):
    # 先按时间差补充至容量上限，再推进时钟。
    bucket["t"] = min(
        bucket["b"], bucket["t"] + (now - bucket["at"]) * bucket["r"]
    )
    bucket["at"] = now

def roll_quota(quota, now):
    # 固定窗口随时钟推进：跨窗（now//span 越过登记窗口）才置
    # window=now//span 并清 used；时钟非递减，窗口只前进不后退。
    window = now // quota["span"]
    if window != quota["window"]:
        quota["window"] = window
        quota["used"] = 0

