    (host, port)，未配置仍建连（无快照，fw 报 STATE）。"""
    record = backends[backend_id]
    record["conns"] += 1
    connections[cid] = [backend_id, flow, now, now]
    endpoint = record["endpoint"]
    if endpoint is not None:
        conn_endpoints[cid] = endpoint

